public class Solution {
    public int[] twoSum(int[] nums, int target) {
        // off-by-one: возвращает i, i вместо i, j
        for (int i = 0; i < nums.length; i++) {
            for (int j = 0; j < nums.length; j++) {
                if (nums[i] + nums[j] == target) return new int[]{i, i};
            }
        }
        return new int[0];
    }
}
